package com.cpf.starter.objectstorage;import java.net.URI;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.s3.*;@AutoConfiguration @EnableConfigurationProperties(CpfObjectStorageProperties.class) @ConditionalOnProperty(prefix="cpf.integration.object-storage",name="enabled",havingValue="true") public class CpfObjectStorageAutoConfiguration {@Bean @ConditionalOnMissingBean S3Client cpfS3Client(CpfObjectStorageProperties p){p.validate();var b=S3Client.builder().region(Region.of(p.getRegion())).serviceConfiguration(S3Configuration.builder().pathStyleAccessEnabled(p.isPathStyle()).build());if(p.getEndpoint()!=null&&!p.getEndpoint().isBlank())b.endpointOverride(URI.create(p.getEndpoint()));return b.build();}@Bean CpfObjectStorageClient cpfObjectStorageClient(S3Client s,CpfObjectStorageProperties p){return new CpfObjectStorageClient(s,p);}}
